<?php
namespace App\Services;
use App\Support\Database;use App\Support\TenantContext;
final class ProjectLifecycleService { public function category(array $p,?string $today=null):string{$today=$today?:date('Y-m-d');if($p['status']==='closed')return 'closed';if($p['status']==='completed')return 'completed';if($p['end_date']<$today)return 'expired';if($p['start_date']>$today)return 'upcoming';return 'open';} public function dashboard():array{$s=Database::pdo()->prepare('SELECT * FROM projects WHERE tenant_id=? ORDER BY end_date');$s->execute([TenantContext::id()]);$out=[];foreach(['open','upcoming','expired','completed','closed'] as $k)$out[$k]=['count'=>0,'revenue'=>0];foreach($s as $p){$k=$this->category($p);$out[$k]['count']++;}$q=Database::pdo()->prepare('SELECT project_id,SUM(total) revenue FROM invoices WHERE tenant_id=? AND project_id IS NOT NULL GROUP BY project_id');$q->execute([TenantContext::id()]);$rev=[];foreach($q as $r)$rev[$r['project_id']]=(float)$r['revenue'];foreach($s as $p){$k=$this->category($p);$out[$k]['revenue']+=($rev[$p['id']]??0);}return $out;} public function close(int $id):void{$s=Database::pdo()->prepare("UPDATE projects SET status='closed',updated_at=NOW() WHERE tenant_id=? AND id=? AND status='completed'");$s->execute([TenantContext::id(),$id]);}}
